import fs from "fs";
import path from "path";
import crypto from "crypto";
import zlib from "zlib";

const targetFile = path.resolve(process.cwd(), "src", "features", "music", "MusicMiniPlayer.tsx");
const expectedSha = "19cbe6daba3c920a61c7cb42aaaa687be1dcd6b0d05b22d5d19fc293488af09e";
const payload = "";

if (!fs.existsSync(targetFile)) {
  console.error(`ERROR: Target file not found: ${targetFile}`);
  console.error("Run this from the MVPTrainerPro-Personal repository root.");
  process.exit(1);
}

const current = fs.readFileSync(targetFile);
const currentSha = crypto.createHash("sha256").update(current).digest("hex");
if (currentSha === expectedSha) {
  console.log("MVP Trainer V5 R8.4.1 is already installed. No changes needed.");
  process.exit(0);
}

const replacement = zlib.inflateSync(Buffer.from(payload, "base64"));
const replacementSha = crypto.createHash("sha256").update(replacement).digest("hex");
if (replacementSha !== expectedSha) {
  console.error("ERROR: Embedded R8.4.1 payload failed SHA verification.");
  process.exit(1);
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupPath = `${targetFile}.bak-r8-4-1-${stamp}`;
fs.copyFileSync(targetFile, backupPath);
fs.writeFileSync(targetFile, replacement);

console.log("MVP Trainer V5 R8.4.1 applied successfully.");
console.log(`Updated: ${path.relative(process.cwd(), targetFile)}`);
console.log(`Backup:  ${path.relative(process.cwd(), backupPath)}`);
console.log(`SHA-256: ${expectedSha}`);
console.log("");
console.log("This self-contained installer embeds the complete replacement file.");
console.log("Next: run npm run build, then test desktop + mobile before committing.");
